Definition cv (e : cedge) : edge :=
  match e with
  | CN m => ENode (N.to_nat m)
  | CI r => EInc r
  | CD r => EDecnz r
  | CB k => EBreak k
  | CC k => EContinue k
  | CH => EHalt
  end.

